import{_ as o,o as r,c as t,a2 as d}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"Rendering Module Overview & Setup","description":"","frontmatter":{},"headers":[],"relativePath":"en/1.21.4/rendering/index.md","filePath":"en/1.21.4/rendering/index.md"}'),n={name:"en/1.21.4/rendering/index.md"};function i(c,e,a,s,l,p){return r(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="rendering-module-overview-setup" tabindex="-1">Rendering Module Overview &amp; Setup <a class="header-anchor" href="#rendering-module-overview-setup" aria-label="Permalink to &quot;Rendering Module Overview &amp; Setup&quot;">​</a></h1><p><code>module.rendering</code> on this branch provides two client rendering pipelines tailored for structural engineering mods:</p><ol><li><strong>In-World Ghost Projection System (<code>projection</code>)</strong>: Bakes any local <code>ProjectionScene</code> into a lightweight, clippable <code>VertexBuffer</code> mesh, using <strong>two-pass rendering (Depth Prepass + Color Pass)</strong> to eliminate translucent self-overlap z-fighting, bypassing shader pipelines to render translucent blueprints at <code>AFTER_LEVEL</code>, and highlighting wrong blocks/states with colored boxes.</li><li><strong>Structure Sandbox &amp; GUI Hover 3D Preview (<code>preview</code>)</strong>: Provides lightweight sandbox level <code>SandboxRenderLevel</code>, <code>ViewportCameraRig</code>, <code>StructurePreviewRenderer</code>, and the floating popup manager <code>StructureGuiPreview</code> for item/screen tooltips.</li></ol><h2 id="module-identity-entry-points" tabindex="-1">Module Identity &amp; Entry Points <a class="header-anchor" href="#module-identity-entry-points" aria-label="Permalink to &quot;Module Identity &amp; Entry Points&quot;">​</a></h2><ul><li>Mod ID: <code>anvillib_rendering</code> (<code>AnvilLibRendering.MOD_ID</code>)</li><li>Resource namespace: <code>AnvilLibRendering.MOD_ID</code></li></ul><h2 id="core-shaders-render-types-projectionshaders-projectionrendertypes" tabindex="-1">Core Shaders &amp; Render Types: <code>ProjectionShaders</code> &amp; <code>ProjectionRenderTypes</code> <a class="header-anchor" href="#core-shaders-render-types-projectionshaders-projectionrendertypes" aria-label="Permalink to &quot;Core Shaders &amp; Render Types: `ProjectionShaders` &amp; `ProjectionRenderTypes`&quot;">​</a></h2><p><code>ProjectionShaders</code> attaches client events via <code>@EventBusSubscriber(modid = AnvilLibRendering.MOD_ID, value = Dist.CLIENT)</code> and registers the built-in core shader <code>anvillib_rendering:core/projection</code> (vertex format <code>DefaultVertexFormat.BLOCK</code>) using <code>net.minecraft.client.renderer.ShaderProgram</code>.</p><table tabindex="0"><thead><tr><th>Class / Member</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><code>ProjectionShaders.register(RegisterShadersEvent event)</code></td><td><code>public static</code></td><td>Registers <code>anvillib_rendering:core/projection</code> <code>ShaderProgram</code> to <code>RegisterShadersEvent</code></td></tr><tr><td><code>ProjectionShaders.reload(ModelEvent.BakingCompleted event)</code></td><td><code>public static</code></td><td>Increments <code>generation</code> and clears <code>ProjectionRenderTypes</code> cache after resource/model rebaking, causing <code>isValid()</code> on old projection meshes to return <code>false</code> and trigger rebuilds</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Because model rebaking invalidates cached <code>ProjectionRenderer</code>s (<code>isValid()</code> returns <code>false</code>), callers should check <code>renderer.isValid()</code> before drawing each frame and call <code>renderer.rebuild(scene, alpha)</code> if <code>false</code> so atlas UVs and block models stay in sync.</p></div><h2 id="projectionbuffers-internal-multi-type-buffer-allocator" tabindex="-1"><code>ProjectionBuffers</code> (Internal Multi-Type Buffer Allocator) <a class="header-anchor" href="#projectionbuffers-internal-multi-type-buffer-allocator" aria-label="Permalink to &quot;`ProjectionBuffers` (Internal Multi-Type Buffer Allocator)&quot;">​</a></h2><p><code>ProjectionBuffers</code> implements <code>MultiBufferSource</code> and <code>AutoCloseable</code> to capture geometry vertices emitted by <code>BlockEntityRenderer</code> and <code>EntityRenderDispatcher</code> in the virtual scene:</p><ul><li>Maps incoming vanilla <code>RenderType</code>s to <code>ProjectionRenderTypes.ghost(type, depthOnly)</code>, disabling depth-occlusion conflicts outside the translucent pass;</li><li>Automatically multiplies and overrides overall projection <code>opacity</code> on every vertex, using <code>depthMask(true) + colorMask(false, false, false, false)</code> in the depth pass and <code>depthMask(false) + colorMask(true, true, true, true)</code> in the color pass.</li></ul>',12)])])}const g=o(n,[["render",i]]);export{h as __pageData,g as default};
